drop table if exists public.highlights cascade;

-- 1) 빈 highlights 테이블 재생성 (스키마는 0001_initial.sql에 이미 포함됨)
-- 만약 DROP 했는데 스키마가 사라졌다면 0001_initial.sql을 먼저 다시 실행
create table if not exists public.highlights (
  id              uuid primary key default gen_random_uuid(),
  contestant_id   uuid not null references public.contestants(id) on delete cascade,
  youtube_id      text not null,
  title           text,
  description     text,
  duration_sec    int,
  source_channel  text,
  sort_order      int not null default 0,
  created_at      timestamptz not null default now()
);
create index if not exists idx_highlights_contestant on public.highlights(contestant_id, sort_order);

